using System.IO.Compression;
using System.Reflection;
using System.Text;

namespace Kosher.Zmanim.Tests.Golden;

/// <summary>
/// Maps KosherJava member names (as recorded in the golden files generated by <c>tools/golden/GoldenGenerator.java</c>)
/// to the members of this port, and reads the golden files.
/// </summary>
internal static class JavaApi
{
    private static readonly Dictionary<string, string> Renames = new()
    {
        ["getDaf"] = "DafNumber",
        ["getZman"] = "Time",
        ["getZoneId"] = "TimeZone",
        ["getCalculatorName"] = "CalculatorName",
        ["isApplyDeltaT"] = "ApplyDeltaT",
    };

    /// <summary>
    /// Returns a function that reads the value of the .NET member corresponding to a parameterless KosherJava getter
    /// (<c>getSunrise</c> -&gt; <c>GetSunrise()</c>, <c>getJewishYear</c> -&gt; <c>JewishYear</c>,
    /// <c>isUseModernHolidays</c> -&gt; <c>UseModernHolidays</c> and so on).
    /// </summary>
    public static Func<object, object?> Getter(Type type, string javaName)
    {
        string pascal = char.ToUpperInvariant(javaName[0]) + javaName.Substring(1);
        var candidates = new List<string>();
        if (Renames.TryGetValue(javaName, out string? renamed))
        {
            candidates.Add(renamed);
        }
        candidates.Add(pascal);
        if (javaName.StartsWith("get", StringComparison.Ordinal))
        {
            candidates.Add(javaName.Substring(3));
        }
        if (javaName.StartsWith("isUse", StringComparison.Ordinal))
        {
            candidates.Add(javaName.Substring(2));
        }
        foreach (string name in candidates)
        {
            MethodInfo? method = type.GetMethod(name, BindingFlags.Public | BindingFlags.Instance, Type.EmptyTypes);
            if (method != null)
            {
                return target => Invoke(method, target);
            }
            PropertyInfo? property = type.GetProperty(name, BindingFlags.Public | BindingFlags.Instance);
            if (property != null && property.GetIndexParameters().Length == 0)
            {
                return target => property.GetValue(target);
            }
        }
        throw new MissingMemberException(type.Name, javaName);
    }

    private static object? Invoke(MethodInfo method, object target)
    {
        try
        {
            return method.Invoke(target, null);
        }
        catch (TargetInvocationException e) when (e.InnerException != null)
        {
            System.Runtime.ExceptionServices.ExceptionDispatchInfo.Capture(e.InnerException).Throw();
            throw;
        }
    }

    /// <summary>Converts a Java <c>UPPER_SNAKE</c> enum constant to the .NET PascalCase member name.</summary>
    public static string PascalConstant(string name)
    {
        var sb = new StringBuilder();
        foreach (string part in name.Split('_', StringSplitOptions.RemoveEmptyEntries))
        {
            sb.Append(char.IsLetter(part[0]) ? part[0] + part.Substring(1).ToLowerInvariant() : part);
        }
        return sb.ToString();
    }

    /// <summary>Maps a Java exception name recorded in a golden file to the .NET exception type.</summary>
    public static Type ExceptionType(string javaName) => javaName switch
    {
        "IllegalArgumentException" => typeof(ArgumentException),
        "IllegalStateException" => typeof(InvalidOperationException),
        "UnsupportedOperationException" => typeof(NotSupportedException),
        "NullPointerException" => typeof(NullReferenceException),
        _ => typeof(Exception),
    };

    /// <summary>Reads the lines of a gzipped golden file from the test output directory.</summary>
    public static IEnumerable<string> ReadLines(string fileName)
    {
        string path = Path.Combine(AppContext.BaseDirectory, "Golden", "Data", fileName);
        using var stream = new GZipStream(File.OpenRead(path), CompressionMode.Decompress);
        using var reader = new StreamReader(stream, Encoding.UTF8);
        string? line;
        while ((line = reader.ReadLine()) != null)
        {
            yield return line;
        }
    }

    /// <summary>Nanoseconds since the Unix epoch of a <see cref="DateTimeOffset"/>.</summary>
    public static long EpochNanos(DateTimeOffset time) => (time.UtcTicks - DateTimeOffset.UnixEpoch.UtcTicks) * 100;
}
